// Build Incident List Response — Panoptes M16

const inputs = $input.all().map(item => item.json);

let rows = [];

for (const input of inputs) {
  if (Array.isArray(input)) {
    rows.push(...input);
  } else if (Array.isArray(input.data)) {
    rows.push(...input.data);
  } else if (
    input.data &&
    typeof input.data === 'object' &&
    !Array.isArray(input.data)
  ) {
    rows.push(input.data);
  } else if (input.incident_id) {
    rows.push(input);
  }
}

const incidents = rows.map(i => ({
  incident_id: i.incident_id,

  workflow: {
    id: i.workflow_id ?? null,
    name: i.workflow_name ?? null
  },

  execution: {
    id: i.execution_id ?? null,
    url: i.execution_url ?? null,
    failed_node: i.failed_node ?? null,
    mode: i.execution_mode ?? null
  },

  diagnosis: {
    failure_type: i.failure_type ?? null,
    transience: i.transience ?? null,
    retry_safety: i.retry_safety ?? null,
    side_effect_risk: i.side_effect_risk ?? null,
    summary: i.diagnosis ?? null,
    confidence: i.diagnosis_confidence ?? null
  },

  recovery: {
    status: i.status ?? null,
    retry_count: i.retry_count ?? 0,
    max_retries: i.max_retries ?? 0,
    proposed_action: i.proposed_action ?? null,
    approval_status: i.approval_status ?? null,
    human_required: i.human_required ?? false
  },

  timestamps: {
    occurred_at: i.occurred_at ?? null,
    created_at: i.created_at ?? null,
    updated_at: i.updated_at ?? null,
    resolved_at: i.resolved_at ?? null
  }
}));

return [{
  json: {
    success: true,
    count: incidents.length,
    incidents
  }
}];

const input = $input.first().json;

const incidentId =
  input.query?.incident_id ??
  input.incident_id ??
  null;

if (!incidentId) {
  throw new Error('Operator API missing incident_id');
}

return [{
  json: {
    incident_id: String(incidentId)
  }
}];

const incident = $('Get Incident').first().json;

if (!incident?.incident_id) {
  return [{
    json: {
      success: false,
      error: 'INCIDENT_NOT_FOUND'
    }
  }];
}

const events = $input
  .all()
  .map(item => item.json)
  .filter(e => e?.event_id);

return [{
  json: {
    success: true,

    incident: {
      incident_id: incident.incident_id,

      workflow: {
        id: incident.workflow_id ?? null,
        name: incident.workflow_name ?? null
      },

      execution: {
        id: incident.execution_id ?? null,
        url: incident.execution_url ?? null,
        failed_node: incident.failed_node ?? null,
        mode: incident.execution_mode ?? null,

        error: {
          name: incident.error_name ?? null,
          message: incident.error_message ?? null
        }
      },

      diagnosis: {
        failure_type: incident.failure_type ?? null,
        transience: incident.transience ?? null,
        retry_safety: incident.retry_safety ?? null,
        side_effect_risk: incident.side_effect_risk ?? null,
        summary: incident.diagnosis ?? null,
        confidence: incident.diagnosis_confidence ?? null
      },

      recovery: {
        status: incident.status ?? null,
        retry_count: incident.retry_count ?? 0,
        max_retries: incident.max_retries ?? 0,
        proposed_action: incident.proposed_action ?? null,
        approval_status: incident.approval_status ?? null,
        human_required: incident.human_required ?? false,
        last_action: incident.last_action ?? null,
        last_action_result: incident.last_action_result ?? null
      },

      config: {
        auto_recovery_enabled:
          incident.auto_recovery_enabled ?? false,

        idempotency_guaranteed:
          incident.idempotency_guaranteed ?? false
      },

      timestamps: {
        occurred_at: incident.occurred_at ?? null,
        created_at: incident.created_at ?? null,
        updated_at: incident.updated_at ?? null,
        resolved_at: incident.resolved_at ?? null
      }
    },

    timeline: events.map(e => ({
      event_id: e.event_id,
      type: e.event_type,
      message: e.event_message,
      old_status: e.old_status,
      new_status: e.new_status,
      tool_name: e.tool_name,
      tool_result: e.tool_result,
      timestamp: e.event_timestamp
    }))
  }
}];

const rows = $input
  .all()
  .map(item => item.json)
  .filter(row => row?.incident_id);

const countStatus = status =>
  rows.filter(row => row.status === status).length;

const failureTypes = {};

for (const row of rows) {
  const type = row.failure_type ?? 'UNKNOWN';
  failureTypes[type] = (failureTypes[type] ?? 0) + 1;
}

const requiringHuman = rows.filter(
  row => row.human_required === true
).length;

const awaitingApproval = rows.filter(
  row =>
    row.status === 'WAITING_FOR_APPROVAL' ||
    row.approval_status === 'PENDING'
).length;

const retryAttempts = rows.reduce(
  (sum, row) => sum + Number(row.retry_count ?? 0),
  0
);

return [{
  json: {
    success: true,

    totals: {
      incidents: rows.length,
      escalated: countStatus('ESCALATED'),
      recovered: countStatus('RECOVERED'),
      recovery_pending: countStatus('RECOVERY_PENDING'),
      recovering: countStatus('RECOVERING'),
      verifying: countStatus('VERIFYING'),
      awaiting_approval: awaitingApproval,
      requiring_human: requiringHuman
    },

    recovery: {
      total_retry_attempts: retryAttempts
    },

    failure_types: failureTypes,

    generated_at: new Date().toISOString()
  }
}];
